  saveProductPriceTiers: async (productId, tiers = []) => {
    const client = getSupabaseClient();
    if (!client) return {
      error: new Error('Supabase client not loaded')
    };
    try {
      const del = await client.from('product_price_tiers').delete().eq('product_id', productId);
      if (del.error) return {
        error: del.error
      };
      if (!tiers.length) return {
        error: null
      };
      const rows = tiers.map((t, idx) => ({
        product_id: productId,
        label: String(t.label || '').trim(),
        qty: t.qty,
        unit: String(t.unit || '').trim(),
        price: t.price,
        is_default: t.is_default === true || t.is_default === undefined && idx === tiers.length - 1,
        show_on_card: t.show_on_card === true,
        sort_order: (idx + 1) * 10
      }));
      const {
        error
      } = await client.from('product_price_tiers').insert(rows);
      return {
        error
      };
    } catch (e) {
      return {
        error: e
      };
    }
  },
