const LucideIcon = ({
  name,
  className = '',
  size = 24,
  strokeWidth = 2,
  ...props
}) => {
  const [ready, setReady] = useState(false);
  useEffect(() => {
    if (window.lucide) {
      setReady(true);
    } else {
      const checkInterval = setInterval(() => {
        if (window.lucide) {
          setReady(true);
          clearInterval(checkInterval);
        }
      }, 50);
      return () => clearInterval(checkInterval);
    }
  }, []);
  if (!ready || !window.lucide || !window.lucide.icons) {
    return React.createElement("span", {
      className: `inline-block ${className}`,
      style: {
        width: size,
        height: size
      }
    });
  }
  let targetName = name;
  if (name === 'Soap') targetName = 'Sparkles';
  if (name === 'Noodle') targetName = 'Soup';
  const pascalName = targetName.replace(/(^\w|-\w)/g, m => m.replace('-', '').toUpperCase());
  const iconNode = window.lucide.icons[pascalName] || window.lucide.icons[targetName];
  if (!iconNode) {
    console.warn(`Icon "${name}" / "${pascalName}" not found in window.lucide.icons`);
    return React.createElement("span", {
      className: `inline-block ${className}`,
      style: {
        width: size,
        height: size
      }
    });
  }
  const renderNode = (node, index) => {
    if (!node) return null;
    if (typeof node === 'string') return node;
    if (!Array.isArray(node)) return null;
    const [tag, attrs, children] = node;
    if (!tag) return null;
    const reactAttrs = {};
    for (const [key, value] of Object.entries(attrs || {})) {
      const camelKey = key === 'class' ? 'className' : key.replace(/-([a-z])/g, g => g[1].toUpperCase());
      reactAttrs[camelKey] = value;
    }
    reactAttrs.key = index;
    const childList = Array.isArray(children) ? children : children ? [children] : [];
    const childElements = childList.length > 0 ? childList.map((child, idx) => renderNode(child, idx)).filter(Boolean) : null;
    return React.createElement(tag, reactAttrs, childElements);
  };
  const svgAttrs = {
    xmlns: "http://www.w3.org/2000/svg",
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: strokeWidth,
    strokeLinecap: "round",
    strokeLinejoin: "round",
    className: `lucide lucide-${name.toLowerCase()} ${className}`,
    ...props
  };
  const iconChildren = Array.isArray(iconNode) && iconNode[0] === 'svg' ? iconNode[2] || [] : iconNode;
  return React.createElement("svg", svgAttrs, (Array.isArray(iconChildren) ? iconChildren : []).map((node, idx) => renderNode(node, idx)).filter(Boolean));
};
