      const unitMatch = line.toLowerCase().match(unitRegex);
      const unit = unitMatch ? normalizeLineUnit(unitMatch[1]) : '';
      const qtyMatch = line.toLowerCase().match(qtyUnitRegex);
      const qty = qtyMatch ? parseFloat(qtyMatch[1].replace(',', '.')) || 1 : 1;
