    if (error) {
      alert(lang === 'id' ? `Gagal kirim reset password: ${error.message || error}` : `Failed to send reset password: ${error.message || error}`);
      return;
    }
    alert(lang === 'id' ? '📧 Link reset password sudah dikirim. Buka email Anda, klik link dari Supabase/Toko Hana, lalu buat password baru.' : '📧 Password reset link has been sent. Open your email, click the link from Supabase/Toko Hana, then create a new password.');
